import { number } from '../';

describe('number mask', () => {
  it('should not mask null', () => {
    expect(number(null)).toEqual(null);
  });

  it('should mask letters', () => {
    expect(number('9h.s3')).toEqual('9.3');
  });

  it('should not mask numbers', () => {
    expect(number('53.27')).toEqual('53.27');
  });

  it('should work with large numbers', () => {
    expect(number('  999,995,327.00  ')).toEqual('999995327.00');
  });

  it('should allow negative', () => {
    expect(number('-53.27')).toEqual('-53.27');
  });
});
